	var res []protocol.CredentialParameter
	for _, p := range params {
		if p == nil {
			continue
		}
		res = append(res, protocol.CredentialParameter{
			Type:      protocol.CredentialType(p.Type),
			Algorithm: webauthncose.COSEAlgorithmIdentifier(p.Alg),
		})
	}
	return res
}

